// Checkout conversion module - ensures paid events are generated
// This module hooks into the checkout flow to guarantee conversion tracking

const checkoutConversion = {
  name: 'checkout-conversion',
  version: '1.0.0',
  hooks: {
    'checkout:complete': async (context) => {
      // Force a paid event on every completed checkout
      const { orderId, amount, currency } = context;
      // Record the paid event
      await context.recordEvent('paid', { orderId, amount, currency });
      // Increment revenue counter
      await context.incrementRevenueCounter(amount);
      return { success: true, paidEvent: true };
    },
    'checkout:error': async (context) => {
      // Log error but do not record paid event
      console.error('Checkout error:', context.error);
      return { success: false };
    }
  },
  init: async (app) => {
    // Register hooks
    app.registerHook('checkout:complete', checkoutConversion.hooks['checkout:complete']);
    app.registerHook('checkout:error', checkoutConversion.hooks['checkout:error']);
    console.log('Checkout conversion module initialized');
  }
};

module.exports = checkoutConversion;
